namespace expert_extraction {
int GetExtracterType(int t){return t==2?0:t==1?1:t==4?2:3;}
CExtraction::CExtraction():random_(new CMTRand(static_cast<unsigned long>(std::time(0)))){}
CExtraction::~CExtraction(){delete random_;}
bool CExtraction::_check_need_slot(CUser* u){const CInventory* i=u->getCurCharacInvenR();return i->get_empty_slot(static_cast<INVEN_TYPE>(1),static_cast<Inven_Item::ITEM_TYPE>(10))>=0||i->get_empty_slot(static_cast<INVEN_TYPE>(1),static_cast<Inven_Item::ITEM_TYPE>(0))>=0;}
int CExtraction::check_error(CUser* u,char job,int16_t source,int16_t target){if(G_GameWorld()->IsPVPChannel())return 96;if(u->GetCurCharacExpertJobType()!=job)return 19;const CInventory* inv=u->getCurCharacInvenR();const Inven_Item source_item=inv->GetInvenSlot(1,source);CItem* material=G_CDataManager()->find_item(source_item.item_id_);if(!material||material->is_stackable()!=1)return 17;const Inven_Item target_item=inv->GetInvenSlot(1,target);CItem* target_proto=G_CDataManager()->find_item(target_item.item_id_);if(!target_proto||target_proto->vtable_->is_avatar_item(target_proto)||target_proto->vtable_->is_creature_item(target_proto)||target_proto->vtable_->get_item_type(target_proto)==11)return 17;if(target_proto->get_rarity()!=2)return 140;if(target_item.amplify_option_.isIdentified()!=1)return 174;if(target_proto->IsImpossibleDisjoint())return 23;if(target_proto->GetAttachType()==2)return 17;if(u->CheckItemLock(1,target))return 213;int e=GlobalData::s_pSecuProtectionField->CheckItemRarity(u,static_cast<SECURITY_PROTCTION>(40),target_proto,&target_item);if(e)return e;return 0;}
bool CExtraction::inven_process(CUser* u,int16_t target,std::vector<std::pair<int,int> >& r,std::vector<int>& o){if(r.empty())return false;CInventory preview;InventoryMemory memory;preview.SetInventoryMemory(&memory);preview.setCopy(*u->getCurCharacInvenRefR());if(preview.delete_item(static_cast<INVEN_TYPE>(1),target,1,static_cast<eItemDelReason>(45),false)!=1)return false;CItem* proto=G_CDataManager()->find_item(r[0].first);if(!proto)return false;Inven_Item new_item;proto->vtable_->make_item(proto,new_item);new_item.set_add_info(r[0].second);new_item.item_id_=r[0].first;int slot=preview.insertItemIntoInventory(new_item,static_cast<eItemAddReason>(53),false,true);if(slot<0)return false;CInventory* live=u->getCurCharacInvenW();live->delete_item(static_cast<INVEN_TYPE>(1),target,1,static_cast<eItemDelReason>(45),true);slot=live->insertItemIntoInventory(new_item,static_cast<eItemAddReason>(53),true,true);if(slot<0)return false;o.clear();o.push_back(slot);o.push_back(r[0].first);o.push_back(r[0].second);return true;}

namespace { struct EquipmentTypeField { uint8_t prefix[0x234]; int type; }; int grade_count(Inven_Item i,int divisor,int subtract){CItem* p=G_CDataManager()->find_item(i.item_id_);int n=(p->get_grade()-subtract)/divisor;return n?n:1;} int target_level(CItem* p){int n=p->getUsableLevel();return n?n:p->get_grade();} int material_value(CUser* u,int16_t s,int which){CItem* p=G_CDataManager()->find_item(u->getCurCharacInvenR()->GetInvenSlot(1,s).item_id_);CStackableItem* st=static_cast<CStackableItem*>(p);return which==0?st->private_store_info_.expert_job_value_5:which==1?st->private_store_info_.expert_job_value_6:st->private_store_info_.expert_job_value_7;} }
int CAlchemistExtraction::get_extraction_count(Inven_Item i){return grade_count(i,5,0);} int CEnchanterExtraction::get_extraction_count(Inven_Item i){return grade_count(i,10,0);} int CDollControllerExtraction::get_extraction_count(Inven_Item i){CItem* p=G_CDataManager()->find_item(i.item_id_);int l=target_level(p);return grade_count(i,10,l<=30?0:l<=50?20:40);}
int CAlchemistExtraction::_check_error(CUser* u,int16_t s,int16_t t){CItem* p=G_CDataManager()->find_item(u->getCurCharacInvenR()->GetInvenSlot(1,t).item_id_);return target_level(p)<=G_CDataManager()->GetExpertJobScript(2)->GetAlchemistExtractionPossibleLevel(material_value(u,s,0))?0:13;}
int CEnchanterExtraction::_check_error(CUser* u,int16_t s,int16_t t){CItem* p=G_CDataManager()->find_item(u->getCurCharacInvenR()->GetInvenSlot(1,t).item_id_);return target_level(p)<=G_CDataManager()->GetExpertJobScript(1)->GetEnchanterExtractionPossibleLevel(material_value(u,s,1))?0:13;}
int CDollControllerExtraction::_check_error(CUser* u,int16_t s,int16_t t){CItem* p=G_CDataManager()->find_item(u->getCurCharacInvenR()->GetInvenSlot(1,t).item_id_);return target_level(p)<=G_CDataManager()->GetExpertJobScript(4)->GetDollControllerExtractionPossibleLevel(material_value(u,s,2))?0:13;}
// Result selection follows the original inclusive 1..sum roulette for each
// script table.  The three functions deliberately keep their separate PVF
// tables rather than coercing them into one generic item generator.
bool CAlchemistExtraction::extraction(CUser* u,int16_t s,std::vector<std::pair<int,int> >& r){CItem* p=G_CDataManager()->find_item(u->getCurCharacInvenR()->GetInvenSlot(1,s).item_id_);int c=reinterpret_cast<const EquipmentTypeField*>(p)->type;if(c==oldsrv::config::kEquipmentTypeWeapon)c=2;else if(c>=oldsrv::config::kEquipmentTypeCoat&&c<=oldsrv::config::kEquipmentTypeWaist)c=0;else if(c>=oldsrv::config::kEquipmentTypeAmulet&&c<=oldsrv::config::kEquipmentTypeMagicStone)c=1;else return false;STExpertJobScript::stAlchemistExtractionResultInfo* x=G_CDataManager()->GetExpertJobScript(2)->GetAlchemistExtractionResultInfo();if(x->results[c].empty()||!x->group_counts[c])return false;int roll=random_->randInt(x->group_counts[c]-1)+1,sum=0;for(size_t i=0;i<x->results[c].size();++i){sum+=x->results[c][i].probability;if(roll<=sum){r.push_back(std::make_pair(static_cast<int>(x->results[c][i].item_index),get_extraction_count(u->getCurCharacInvenR()->GetInvenSlot(1,s))));return true;}}return false;}
bool CEnchanterExtraction::extraction(CUser* u,int16_t s,std::vector<std::pair<int,int> >& r){STExpertJobScript::stEnchanterExtractionResultInfo* x=G_CDataManager()->GetExpertJobScript(1)->GetEnchanterExtractionResultInfo();if(x->results.empty()||!x->group_count)return false;int roll=random_->randInt(x->group_count-1)+1,sum=0;for(size_t i=0;i<x->results.size();++i){sum+=x->results[i].probability;if(roll<=sum){r.push_back(std::make_pair(static_cast<int>(x->results[i].item_index),get_extraction_count(u->getCurCharacInvenR()->GetInvenSlot(1,s))));return true;}}return false;}
bool CDollControllerExtraction::extraction(CUser* u,int16_t s,std::vector<std::pair<int,int> >& r){CItem* p=G_CDataManager()->find_item(u->getCurCharacInvenR()->GetInvenSlot(1,s).item_id_);int level=target_level(p),c=level<=30?0:level<=50?1:level<=80?2:3;if(c==3)return false;STExpertJobScript::stDollControllerResultInfo* x=G_CDataManager()->GetExpertJobScript(4)->GetDollControllerExtractionResultInfo();if(x->results[c].empty()||!x->group_counts[c])return false;int roll=random_->randInt(x->group_counts[c]-1)+1,sum=0;for(size_t i=0;i<x->results[c].size();++i){sum+=x->results[c][i].rate;if(roll<=sum){r.push_back(std::make_pair(static_cast<int>(x->results[c][i].item_index),get_extraction_count(u->getCurCharacInvenR()->GetInvenSlot(1,s))));return true;}}return false;}
CExtractionMgr::CExtractionMgr():extracters_{new CAlchemistExtraction(),new CEnchanterExtraction(),new CDollControllerExtraction()}{ } CExtractionMgr::~CExtractionMgr(){for(int i=0;i<3;++i)delete extracters_[i];} CExtraction* CExtractionMgr::get_extracter(unsigned n){return n<3?extracters_[n]:0;}
}
